function subjectCard(s){return `<a href="#subject-${s.id}" class="explore-card tone-${s.color||"pink"}" data-subject="${s.id}"><div class="explore-card-top"><span class="explore-emoji">${s.icon}</span><span class="card-arrow">↗</span></div><h3>${localized(s,"name")}</h3><p>${localized(s,"description")}</p><div class="card-meta"><span>${s.lessons.length} ${t("lessons")}</span><span>${t("viewSubject")} →</span></div></a>`}
function renderSubject(id){
 const s=subjectData.find(x=>x.id===id);if(!s){renderExplore();return}
 updateNav();
 pageContent.innerHTML=`<div class="stage-page"><button class="back-link" id="backExplore">← ${t("backExplore")}</button><div class="subject-hero tone-${s.color||"pink"}"><div><div class="stage-eyebrow">${t("whatYouLearn")}</div><h1 class="stage-title">${s.icon} ${localized(s,"name")}</h1><p class="stage-subtitle">${localized(s,"description")}</p><span class="subject-count">${s.lessons.length} ${t("lessonCount")}</span></div><div class="subject-hero-art">${s.icon}</div></div><div class="section-heading stage-section-heading"><div><div class="section-kicker">${t("previewLabel")}</div><h2>${currentLanguage==="id"?"Mulai dari sini":"Start here"}</h2></div></div><div class="lesson-list">${s.lessons.map(l=>lessonCard(l,s)).join("")}</div></div>`;
 $("#backExplore").addEventListener("click",()=>navigate("explore"));
 document.querySelectorAll("[data-lesson]").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();navigate("lesson-"+s.id+"-"+a.dataset.lesson)}));
}
function lessonCard(l,s){return `<a href="#lesson-${s.id}-${l.id}" class="lesson-card" data-lesson="${l.id}"><span class="lesson-icon">${s.icon}</span><span class="lesson-info"><small>${t("lesson")} · ${l.duration}</small><strong>${localized(l,"title")}</strong><p>${localized(l,"summary")}</p></span><span class="lesson-go">→</span></a>`}
function renderLesson(combined){
 const parts=combined.split("-");const lessonId=parts.pop();const subjectId=parts.join("-");const s=subjectData.find(x=>x.id===subjectId);const l=s?.lessons.find(x=>x.id===lessonId);
 if(!s||!l){renderExplore();return}
 updateNav();
 pageContent.innerHTML=`<div class="stage-page lesson-page"><button class="back-link" id="backSubject">← ${localized(s,"name")}</button><article class="lesson-article"><div class="lesson-article-icon">${s.icon}</div><div class="stage-eyebrow">${t("previewLabel")} · ${l.duration}</div><h1 class="stage-title">${localized(l,"title")}</h1><p class="stage-subtitle">${localized(l,"summary")}</p><div class="lesson-divider"></div><p class="lesson-body">${localized(l,"body")}</p><h3 class="takeaway-title">${t("keyIdeas")}</h3><ul class="takeaway-list">${(currentLanguage==="id"?l.points_id:l.points).map(p=>`<li>${p}</li>`).join("")}</ul><div class="lesson-note">🌱 ${t("contentNote")}</div><button class="primary-button lesson-done" id="lessonDone">${t("lessonComplete")} <span>✓</span></button></article></div>`;
 $("#backSubject").addEventListener("click",()=>navigate("subject-"+s.id));
 $("#lessonDone").addEventListener("click",()=>{showToast(t("lessonCompleteMsg"));navigate("subject-"+s.id)});
}
function escapeHTML(str){return String(str).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function openModal(){const o=$("#modalOverlay");o.classList.add("open");o.setAttribute("aria-hidden","false")}
function closeModal(){const o=$("#modalOverlay");o.classList.remove("open");o.setAttribute("aria-hidden","true")}
function bindGlobal(){
 $("#languageToggle").addEventListener("click",()=>{currentLanguage=currentLanguage==="id"?"en":"id";applyLanguage();showToast(currentLanguage==="id"?"Bahasa Indonesia aktif":"English is now active")});
 $("#accountButton").addEventListener("click",openModal);$("#profileButton").addEventListener("click",openModal);
 $("#modalClose").addEventListener("click",closeModal);$("#guestContinue").addEventListener("click",()=>{closeModal();showToast(currentLanguage==="id"?"Kamu sedang menjelajah sebagai tamu 🌷":"You're exploring as a guest 🌷")});
 $("#createAccount").addEventListener("click",()=>showToast(currentLanguage==="id"?"Fitur akun akan hadir pada tahap berikutnya.":"Account features are coming in a later stage."));
 $("#modalOverlay").addEventListener("click",e=>{if(e.target.id==="modalOverlay")closeModal()});
 document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
 $("#notificationButton").addEventListener("click",()=>showToast(currentLanguage==="id"?"Belum ada notifikasi baru.":"No new notifications."));
 $("#menuToggle").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
 document.addEventListener("click",e=>{if(innerWidth<=760&&!$("#sidebar").contains(e.target)&&!e.target.closest("#menuToggle"))$("#sidebar").classList.remove("open")});
 document.querySelectorAll(".nav-link").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();navigate(a.dataset.page)}));
 bindHome();
}
function start(){
 bindGlobal();applyStaticLanguage();updateDate();syncHomeXP();
 const initial=location.hash.slice(1);if(initial==="explore")renderExplore();else if(initial.startsWith("subject-"))renderSubject(initial.slice(8));else if(initial.startsWith("lesson-"))renderLesson(initial.slice(7));else if(initial==="quiz")renderQuizHome();else if(initial==="library")renderFlashcards();else if(initial==="garden")renderGarden();else setPageLabel("home");
 window.addEventListener("popstate",()=>{const h=location.hash.slice(1);if(h==="explore")renderExplore();else if(h.startsWith("subject-"))renderSubject(h.slice(8));else if(h.startsWith("lesson-"))renderLesson(h.slice(7));else if(h==="quiz")renderQuizHome();else if(h==="library")renderFlashcards();else if(h==="garden")renderGarden();else{pageContent.innerHTML=homeMarkup;bindHome();applyStaticLanguage();setPageLabel("home");syncHomeXP()}});
}
start();


